import { useState } from 'react';
import { Field, IdNotice, ImageUpload, Modal } from './ui';
import { api } from '../services/api';
import { useToast } from '../context/ToastContext';

const EMPTY = { firstName: '', lastName: '', company: '', email: '', phoneNumber: '', address: '', imageUrl: '' };

/* Add / edit customer. Only the name is required – the ID is generated by the backend. */
export default function CustomerForm({ customer, onClose, onSaved, quick = false }) {
  const toast = useToast();
  const editing = Boolean(customer?.custID);
  const [form, setForm] = useState({ ...EMPTY, ...(customer || {}) });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e?.target ? e.target.value : e }));

  const save = async (e) => {
    e?.preventDefault();
    if (!form.firstName.trim()) { setError('Please enter the customer\'s name.'); return; }
    setBusy(true);
    setError('');
    try {
      const saved = editing ? await api.customers.update(form) : await api.customers.create({ ...form, custID: '' });
      toast.success(editing ? 'Customer updated' : 'Customer added', `${saved.firstName} ${saved.lastName} · ${saved.custID}`);
      onSaved?.(saved);
      onClose();
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Modal title={editing ? 'Edit customer' : quick ? 'Add a new customer' : 'Add customer'}
      subtitle={quick ? 'They\'ll be selected for this sale straight away.' : 'Only the name is required.'}
      onClose={onClose}
      footer={<>
        <button className="btn btn-secondary" onClick={onClose} disabled={busy}>Cancel</button>
        <button className="btn btn-primary" onClick={save} disabled={busy}>{busy ? 'Saving…' : editing ? 'Save changes' : 'Add customer'}</button>
      </>}>
      <form onSubmit={save} className="form-grid">
        <div className="full"><IdNotice id={form.custID} prefix="CUS" /></div>
        {!quick && <Field full label="Picture"><ImageUpload value={form.imageUrl} onChange={set('imageUrl')} name={form.firstName} round onError={(m) => toast.error('Image', m)} /></Field>}
        <Field label="First name" required><input className="input" value={form.firstName} onChange={set('firstName')} autoFocus placeholder="e.g. Sipho" /></Field>
        <Field label="Last name"><input className="input" value={form.lastName} onChange={set('lastName')} placeholder="e.g. Ndlovu" /></Field>
        <Field full label="Business / shop name"><input className="input" value={form.company} onChange={set('company')} placeholder="e.g. Ndlovu Spaza Shop" /></Field>
        <Field label="Phone"><input className="input" value={form.phoneNumber} onChange={set('phoneNumber')} placeholder="072 123 4567" /></Field>
        <Field label="Email"><input className="input" type="email" value={form.email} onChange={set('email')} placeholder="name@example.co.za" /></Field>
        <Field full label="Address"><input className="input" value={form.address} onChange={set('address')} placeholder="Street, suburb, city" /></Field>
        {error && <div className="full text-danger small">{error}</div>}
        <button type="submit" hidden />
      </form>
    </Modal>
  );
}
